    "\u{1F385}\u{1F3FD}": "\u8056\u8A95\u8001\u4EBA\uFF1A\u6DFA\u8910\u76AE\u819A \u6DFA\u8910\u76AE\u819A \u7238\u7238 \u8056\u8A95 \u8056\u8A95\u8001\u4EBA \u8056\u8A95\u8001\u516C\u516C",
