    "\u{1F936}\u{1F3FD}": "\u8056\u8A95\u8001\u5976\u5976\uFF1A\u6DFA\u8910\u76AE\u819A \u5ABD\u5ABD \u6DFA\u8910\u76AE\u819A \u7AE5\u8A71 \u8056\u8A95\u7BC0 \u8056\u8A95\u8001\u5976\u5976",
