    "\u{1F9B8}\u{1F3FD}\u200D\u2640\uFE0F": "\u5973\u8D85\u4EBA\uFF1A\u6DFA\u8910\u76AE\u819A \u5929\u8CE6 \u5973\u82F1\u96C4 \u5973\u8D85\u4EBA \u6DFA\u8910\u76AE\u819A \u82F1\u96C4 \u8D85\u80FD\u529B",
