    "\u{1F574}\uFE0F": "\u7A7F\u897F\u88DD\u7684\u4EBA \u7A7F\u8457\u6B63\u5F0F \u897F\u88DD",
    "\u{1F574}\u{1F3FB}": "\u7A7F\u897F\u88DD\u7684\u4EBA\uFF1A\u767D\u76AE\u819A \u767D\u76AE\u819A \u7A7F\u8457\u6B63\u5F0F \u7A7F\u897F\u88DD\u7684\u4EBA \u897F\u88DD",
    "\u{1F574}\u{1F3FC}": "\u7A7F\u897F\u88DD\u7684\u4EBA\uFF1A\u9EC3\u76AE\u819A \u7A7F\u8457\u6B63\u5F0F \u7A7F\u897F\u88DD\u7684\u4EBA \u897F\u88DD \u9EC3\u76AE\u819A",
    "\u{1F574}\u{1F3FD}": "\u7A7F\u897F\u88DD\u7684\u4EBA\uFF1A\u6DFA\u8910\u76AE\u819A \u6DFA\u8910\u76AE\u819A \u7A7F\u8457\u6B63\u5F0F \u7A7F\u897F\u88DD\u7684\u4EBA \u897F\u88DD",
    "\u{1F574}\u{1F3FE}": "\u7A7F\u897F\u88DD\u7684\u4EBA\uFF1A\u8910\u76AE\u819A \u7A7F\u8457\u6B63\u5F0F \u7A7F\u897F\u88DD\u7684\u4EBA \u8910\u76AE\u819A \u897F\u88DD",
    "\u{1F574}\u{1F3FF}": "\u7A7F\u897F\u88DD\u7684\u4EBA\uFF1A\u9ED1\u76AE\u819A \u7A7F\u8457\u6B63\u5F0F \u7A7F\u897F\u88DD\u7684\u4EBA \u897F\u88DD \u9ED1\u76AE\u819A",
    "\u{1F46F}": "\u5154\u5973\u90CE \u5154\u8033 \u6B7B\u9EE8 \u8D70\u8DB4 \u8DF3\u821E \u95A8\u871C \u96D9\u80DE\u80CE \u9AD8\u8869",
    "\u{1F46F}\u{1F3FB}": "\u5154\u5973\u90CE\uFF1A\u767D\u76AE\u819A \u5154\u5973\u90CE \u5154\u8033 \u6B7B\u9EE8 \u767D\u76AE\u819A \u8D70\u8DB4 \u8DF3\u821E \u95A8\u871C \u96D9\u80DE\u80CE \u9AD8\u8869",
    "\u{1F46F}\u{1F3FC}": "\u5154\u5973\u90CE\uFF1A\u9EC3\u76AE\u819A \u5154\u5973\u90CE \u5154\u8033 \u6B7B\u9EE8 \u8D70\u8DB4 \u8DF3\u821E \u95A8\u871C \u96D9\u80DE\u80CE \u9AD8\u8869 \u9EC3\u76AE\u819A",
    "\u{1F46F}\u{1F3FD}": "\u5154\u5973\u90CE\uFF1A\u6DFA\u8910\u76AE\u819A \u5154\u5973\u90CE \u5154\u8033 \u6B7B\u9EE8 \u6DFA\u8910\u76AE\u819A \u8D70\u8DB4 \u8DF3\u821E \u95A8\u871C \u96D9\u80DE\u80CE \u9AD8\u8869",
    "\u{1F46F}\u{1F3FE}": "\u5154\u5973\u90CE\uFF1A\u8910\u76AE\u819A \u5154\u5973\u90CE \u5154\u8033 \u6B7B\u9EE8 \u8910\u76AE\u819A \u8D70\u8DB4 \u8DF3\u821E \u95A8\u871C \u96D9\u80DE\u80CE \u9AD8\u8869",
    "\u{1F46F}\u{1F3FF}": "\u5154\u5973\u90CE\uFF1A\u9ED1\u76AE\u819A \u5154\u5973\u90CE \u5154\u8033 \u6B7B\u9EE8 \u8D70\u8DB4 \u8DF3\u821E \u95A8\u871C \u96D9\u80DE\u80CE \u9AD8\u8869 \u9ED1\u76AE\u819A",
